<?php
require 'config.php';require 'auth.php';require 'helpers.php';require_login();$id=(int)($_GET['id']??$_POST['id']??0);$uid=current_user_id();$error='';$stmt=$conn->prepare("SELECT b.*,ts.start_time,c.court_name,f.facility_name FROM bookings b JOIN time_slots ts ON ts.id=b.time_slot_id JOIN courts c ON c.id=b.court_id JOIN facilities f ON f.id=c.facility_id WHERE b.id=? AND b.user_id=?");$stmt->bind_param('ii',$id,$uid);$stmt->execute();$b=$stmt->get_result()->fetch_assoc();if(!$b){http_response_code(404);die('Booking not found.');}if($b['status']!=='confirmed'||booking_has_started($b['booking_date'],$b['start_time'])){http_response_code(400);die('This booking can no longer be edited.');}if($_SERVER['REQUEST_METHOD']==='POST'){$purpose=trim($_POST['purpose']??'');$participants=(int)($_POST['participants']??0);if($purpose===''||$participants<1||$participants>50)$error='Enter a purpose and 1-50 participants.';else{$stmt=$conn->prepare('UPDATE bookings SET purpose=?,participants=? WHERE id=? AND user_id=?');$stmt->bind_param('siii',$purpose,$participants,$id,$uid);$stmt->execute();header('Location: confirmation.php?id='.$id);exit;}}$pageTitle='Edit Booking';require 'partials/header.php';?>
<div class="form-card"><h1>Edit Booking</h1><p><?=htmlspecialchars($b['facility_name'].' - '.$b['court_name'])?><br><?=htmlspecialchars(date('d M Y, g:i A',strtotime($b['booking_date'].' '.$b['start_time'])))?></p><?php if($error):?><p class="alert alert-error"><?=htmlspecialchars($error)?></p><?php endif;?><form method="post"><input type="hidden" name="id" value="<?=$id?>"><label>Purpose <input name="purpose" maxlength="180" value="<?=htmlspecialchars($_POST['purpose']??$b['purpose'])?>" required></label><label>Participants <input type="number" name="participants" min="1" max="50" value="<?=(int)($_POST['participants']??$b['participants'])?>" required></label><button>Save Changes</button> <a class="btn btn-secondary" href="index.php">Cancel</a></form></div><?php require 'partials/footer.php';?>

